import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Durable Execution and Recovery","description":"The Run lifecycle, task graph, lease, recovery strategy, routing, and MVP relationships of the Hearth Durable Harness.","frontmatter":{"title":"Durable Execution and Recovery","description":"The Run lifecycle, task graph, lease, recovery strategy, routing, and MVP relationships of the Hearth Durable Harness.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/durable-execution.md","filePath":"en/architecture/durable-execution.md","lastUpdated":1793706118000}'),i={name:"en/architecture/durable-execution.md"};function l(r,e,o,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s(`<p class="eyebrow">DURABLE HARNESS</p><h1 id="durable-execution-and-recovery" tabindex="-1">Durable Execution and Recovery <a class="header-anchor" href="#durable-execution-and-recovery" aria-label="Permalink to &quot;Durable Execution and Recovery&quot;">​</a></h1><p class="lead">Long-running tasks must survive crashes, sleep, network interruptions, and Executor failures. The Durable Harness is responsible for turning intent into recoverable execution.</p><h2 id="durable-harness" tabindex="-1">Durable Harness <a class="header-anchor" href="#durable-harness" aria-label="Permalink to &quot;Durable Harness&quot;">​</a></h2><p>The Harness is the middle layer that &quot;turns an intent into recoverable execution&quot;:</p><ul><li>Receives decisions from the Control Plane;</li><li>Builds the task graph;</li><li>Selects Executors;</li><li>Enforces budgets and leases;</li><li>Handles cancellation, retries, and recovery;</li><li>Turns results into Artifacts, Receipts, and Eval.</li></ul><p>It is not a model, nor is it a Sandbox.</p><h3 id="run-lifecycle" tabindex="-1">Run Lifecycle <a class="header-anchor" href="#run-lifecycle" aria-label="Permalink to &quot;Run Lifecycle&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>created</span></span>
<span class="line"><span>  → authorized</span></span>
<span class="line"><span>  → queued</span></span>
<span class="line"><span>  → assigned</span></span>
<span class="line"><span>  → running</span></span>
<span class="line"><span>  → verifying</span></span>
<span class="line"><span>  → completed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exception branches:</span></span>
<span class="line"><span>  → paused</span></span>
<span class="line"><span>  → waiting_approval</span></span>
<span class="line"><span>  → waiting_input</span></span>
<span class="line"><span>  → retry_wait</span></span>
<span class="line"><span>  → failed</span></span>
<span class="line"><span>  → cancelled</span></span>
<span class="line"><span>  → needs_human</span></span></code></pre></div><p>Every state transition must:</p><ul><li>Produce an event;</li><li>Have an explicit trigger;</li><li>Have idempotency conditions;</li><li>Be replayable from events;</li><li>Never overwrite history in place.</li></ul><h3 id="task-graph" tabindex="-1">Task Graph <a class="header-anchor" href="#task-graph" aria-label="Permalink to &quot;Task Graph&quot;">​</a></h3><p>Supports sequential dependencies, parallel branches, joins, failure propagation, compensation tasks, human approval nodes, cross-day waits, long-task checkpoints, and subtask budget inheritance.</p><p>Phase one does not introduce a heavyweight workflow engine; it uses explicit state machines, SQLite, outbox, timers, and leases, plus clear intermediate artifacts.</p><h3 id="lease-and-single-writer" tabindex="-1">Lease and Single Writer <a class="header-anchor" href="#lease-and-single-writer" aria-label="Permalink to &quot;Lease and Single Writer&quot;">​</a></h3><ul><li>Each Ticket has at most one valid Assignment at any given moment;</li><li>An Executor or device must hold a lease to make progress;</li><li>After a lease expires, it can be reassigned;</li><li>Reassignment must carry a fencing token, rejecting continued writes from the old executor;</li><li>The same State Root has only one write authority;</li><li>Device-local state is only a cache;</li><li>When a device is offline, tasks are queued; upon reconnection, they resume by cursor, lease, and checkpoint;</li><li>Device loss must revoke the lease, capability, and keys.</li></ul><h3 id="recovery-strategy" tabindex="-1">Recovery Strategy <a class="header-anchor" href="#recovery-strategy" aria-label="Permalink to &quot;Recovery Strategy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Failure</th><th>Recovery Method</th></tr></thead><tbody><tr><td>Process crash</td><td>Recover from Event Log and checkpoints</td></tr><tr><td>Network interruption</td><td>Retain outbox; redeliver by idempotency key after recovery</td></tr><tr><td>Executor timeout</td><td>Save workspace snapshot; retry or switch Executor</td></tr><tr><td>Device offline</td><td>Enter device queue; do not lose tasks</td></tr><tr><td>Uncertain external result</td><td>Mark as uncertain; reconcile first, do not blindly retry</td></tr><tr><td>Memory conflict</td><td>Preserve source; do not silently overwrite</td></tr></tbody></table><p>After recovery, re-verification is mandatory; do not trust old natural-language &quot;completion.&quot;</p><h3 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ticket</span></span>
<span class="line"><span>  → Capability matching</span></span>
<span class="line"><span>  → Risk and permission check</span></span>
<span class="line"><span>  → Token / cost / latency estimate</span></span>
<span class="line"><span>  → Select Executor or Human</span></span>
<span class="line"><span>  → Execute</span></span>
<span class="line"><span>  → Validation failed?</span></span>
<span class="line"><span>      ├─ Retry with the same Executor</span></span>
<span class="line"><span>      ├─ Switch to a more suitable Executor</span></span>
<span class="line"><span>      ├─ Degrade to a smaller scope</span></span>
<span class="line"><span>      └─ Human takeover</span></span></code></pre></div><p>Routing should not be decided by the model alone. Rules, historical success rates, cost, permissions, and device state all participate.</p><h3 id="boundary-rules" tabindex="-1">Boundary Rules <a class="header-anchor" href="#boundary-rules" aria-label="Permalink to &quot;Boundary Rules&quot;">​</a></h3><ol><li>The Control Plane does not execute tools directly.</li><li>The Harness does not read raw credentials directly.</li><li>The Executor does not decide &quot;whether it is allowed.&quot;</li><li>The Execution Gateway does not decide business intent.</li><li>The UI cannot bypass Policy to write to the database or trigger tools.</li><li>All external side effects go through the outbox, idempotency keys, and Receipt.</li><li>All schema changes come with migrations and compatibility tests.</li></ol><h2 id="relationship-to-the-mvp" tabindex="-1">Relationship to the MVP <a class="header-anchor" href="#relationship-to-the-mvp" aria-label="Permalink to &quot;Relationship to the MVP&quot;">​</a></h2><p>The MVP does not need to fully implement the Gateway, Trigger, device catalog, and all recovery policies, but it must have a minimal real chain:</p><ul><li>Web input enters the Gateway → Event;</li><li>The Control Plane creates a Task/Ticket;</li><li>The Harness persists the Run and state;</li><li>Codex executes and produces events;</li><li>The validator decides completion;</li><li>The Web displays task cards and recovery entry points from the projection.</li></ul><p>Without this chain, it is not an MVP—it is just a frontend demo or a backend library.</p>`,28)])])}const y=a(i,[["render",l]]);export{h as __pageData,y as default};
